package vn.rtr.aeris.phone06;
import java.io.*;import java.net.*;import java.nio.charset.StandardCharsets;import java.util.*;
/** Engineering USB admission, not hardware attestation. All time arithmetic is Android-local. */
public final class PhoneAdmission06 {
 public static final String AP_SHA="011627d41dd95640c3aca02d45283474be48721c8b1bb7a4b234d38b69063482";
 private final RawJournal95.Clock clock;private final String activityBoot=UUID.randomUUID().toString();private final Set<String>used=new HashSet<>();private Map<String,Object>binding;private long expires=-1;private String activeNonce=null,readCapability=null;
 public PhoneAdmission06(RawJournal95.Clock c){clock=c;}
 public synchronized Map<String,Object>challenge06(Map<String,Object>owned,String source)throws Exception{clear();if(used.size()>=4)throw new IOException("PHONE_ADMISSION_ATTEMPT_BOUND");String nonce=UUID.randomUUID().toString();used.add(nonce);activeNonce=nonce;return Data97.m("format","aeris-phone06-challenge","nonce",nonce,"activityBoot",activityBoot,"sourceId",source,"run",owned.get("run"),"containerId",owned.get("containerId"),"binarySha256",AP_SHA);}
 public Map<String,Object>verify(Map<String,Object>owned,String source)throws Exception{Map<String,Object>q=challenge06(owned,source);long begin=clock.now();byte[]request=(Data97.json(q)+"\n").getBytes(StandardCharsets.UTF_8);try{byte[]raw;try(Socket socket=new Socket()){socket.connect(new InetSocketAddress("127.0.0.1",5961),3000);socket.getOutputStream().write(request);socket.getOutputStream().flush();ByteArrayOutputStream b=new ByteArrayOutputStream();InputStream in=socket.getInputStream();while(true){long remaining=3000-(clock.now()-begin);if(remaining<=0||remaining>3000)throw new IOException("PHONE_ADMISSION_DEADLINE");socket.setSoTimeout((int)remaining);int ch=in.read();if(ch<0)throw new EOFException("PHONE_ADMISSION_EOF");if(ch==10)break;if(b.size()>=16384)throw new IOException("PHONE_ADMISSION_BYTE_BOUND");b.write(ch);}raw=b.toByteArray();}return accept(StrictJson02.parse(raw),q,begin,clock.now());}catch(Exception e){synchronized(this){if(Objects.equals(activeNonce,q.get("nonce")))clear();}throw e;}}
 synchronized Map<String,Object>accept(Map<String,Object>r,Map<String,Object>q,long begin,long end)throws Exception{
  if(activeNonce==null||!Objects.equals(activeNonce,q.get("nonce")))throw new IOException("PHONE_ADMISSION_SUPERSEDED_CHALLENGE");binding=null;expires=-1;activeNonce=null;if(end<begin||end-begin>3000||!Boolean.TRUE.equals(r.get("ok"))||!"aeris-phone06-admission".equals(r.get("format")))throw new IOException("PHONE_ADMISSION_CONTEXT");
  for(String k:Arrays.asList("nonce","activityBoot","sourceId","run","containerId","binarySha256"))if(!Objects.equals(r.get(k),q.get(k)))throw new IOException("PHONE_ADMISSION_BINDING:"+k);
  long remaining=StrictJson02.integer(r,"remainingDurationMs");if(remaining<1||remaining>900000||remaining<=end-begin||!Boolean.TRUE.equals(r.get("simulationOnly"))||!Boolean.FALSE.equals(r.get("hardwareAuthenticated")))throw new IOException("PHONE_ADMISSION_LEASE");
  if(!(r.get("manualActualQualified")instanceof Boolean)||!(r.get("neutralProbeAllowed")instanceof Boolean))throw new IOException("PHONE_ADMISSION_QUALIFICATION");
  String cap=(String)r.get("observerReadCapability");if(cap!=null&&!cap.matches("[a-f0-9]{64}"))throw new IOException("PHONE_OBSERVER_CAPABILITY_FORMAT");readCapability=cap;binding=new LinkedHashMap<>(r);binding.remove("observerReadCapability");binding.put("phoneReceivedAtMs",end);binding.put("requestRttMs",end-begin);expires=end+remaining-(end-begin);binding.put("phoneExpiresAtMs",expires);return snapshot();
 }
 public synchronized void require(String run,boolean manual)throws IOException{long n=clock.now();if(binding==null||n<(long)binding.get("phoneReceivedAtMs")||n>=expires||!Objects.equals(run,binding.get("run"))||manual&&!Boolean.TRUE.equals(binding.get("manualActualQualified")))throw new IOException(manual?"PHONE_MANUAL_ACTUAL_NOT_QUALIFIED_OR_ADMISSION_STALE":"PHONE_SIMULATION_ADMISSION_REQUIRED");}
 public synchronized void clear(){binding=null;expires=-1;activeNonce=null;readCapability=null;} synchronized String capability06(String run)throws IOException{require(run,false);return readCapability;} public synchronized boolean probe(String run)throws IOException{require(run,false);return Boolean.TRUE.equals(binding.get("neutralProbeAllowed"));}
 public synchronized Map<String,Object>snapshot(){return binding==null?Data97.m("admitted",false,"manualActualQualified",false):new LinkedHashMap<>(binding);}
}
